import{c as a,Z as l,Q as n,j as s,g as e,n as d,a3 as c,m as u,o}from"./chunks/framework.7Akk-szY.js";const k=JSON.parse('{"title":"IntelliJ IDEA","description":"","frontmatter":{"title":"IntelliJ IDEA","status":"draft","tags":["env","all","module0"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"java-quick-start/intellij.md","filePath":"java-quick-start/intellij.md"}'),m={name:"java-quick-start/intellij.md"},p={id:"frontmatter-title",tabindex:"-1"},g={tabindex:"0"};function h(i,t,b,f,v,q){const r=l("ColorChip");return n(),s("div",null,[e("h1",p,[d(c(i.$frontmatter.title)+" ",1),t[0]||(t[0]=e("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),t[8]||(t[8]=u('<p><em>Intellij</em> IDEA est l&#39;environnement de développement intégré (IDE) recommandé pour ce cours. Il offre des outils puissants pour écrire, déboguer et refactoriser du code Java efficacement.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Installer et configurer <em>Intellij</em> Community Edition</li><li>Naviguer dans les fenêtres principales de l&#39;IDE</li><li>Utiliser les raccourcis clavier essentiels</li><li>Lire et interpréter les messages d&#39;erreur et avertissements</li><li>Configurer l&#39;IDE pour le cours (désactiver certaines fonctions automatiques)</li></ul></div><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Télécharge <strong><em>Intellij</em> IDEA Community Edition</strong> (gratuite) depuis <a href="https://www.jetbrains.com/idea/" target="_blank" rel="noreferrer">jetbrains.com/idea</a>. La version Community suffit pour tout le cours.</p><div class="tip custom-block"><p class="custom-block-title">Configuration du cours</p><p>Le cours fournit un fichier de paramètres à importer dans <em>Intellij</em>. Ce fichier configure les raccourcis, le style de code et les inspections conformément aux normes du cours.</p><p>Pour importer : <strong>File → Manage IDE Settings → Import Settings</strong></p></div><h2 id="fenetres-principales" tabindex="-1">Fenêtres principales <a class="header-anchor" href="#fenetres-principales" aria-label="Permalink to &quot;Fenêtres principales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fenêtre</th><th>Rôle</th></tr></thead><tbody><tr><td><strong>Project</strong> (à gauche)</td><td>Navigation dans l&#39;arborescence de fichiers</td></tr><tr><td><strong>Editor</strong> (au centre)</td><td>Édition du code source</td></tr><tr><td><strong>Terminal</strong> (en bas)</td><td>Ligne de commande intégrée</td></tr><tr><td><strong>Problems</strong> (en bas)</td><td>Erreurs et avertissements détectés</td></tr><tr><td><strong>Git</strong> (en bas)</td><td>Gestion du contrôle de version</td></tr><tr><td><strong>Run/Debug</strong> (en bas)</td><td>Résultats d&#39;exécution et débogage</td></tr></tbody></table><h2 id="raccourcis-essentiels" tabindex="-1">Raccourcis essentiels <a class="header-anchor" href="#raccourcis-essentiels" aria-label="Permalink to &quot;Raccourcis essentiels&quot;">​</a></h2><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Clic</code></td><td>Aller à la définition d&#39;une méthode ou <a href="/420-w20-sf-po1/lexique.html#classe" class="lexicon-link" title="Modèle (blueprint) qui décrit les attributs et les méthodes d&#39;un type d&#39;objet.">classe</a></td></tr><tr><td><code>Ctrl+Alt+←</code> / <code>Ctrl+Alt+→</code></td><td>Reculer / avancer dans l&#39;historique de navigation</td></tr><tr><td><code>Shift+Shift</code></td><td>Rechercher n&#39;importe quel fichier, classe ou action</td></tr></tbody></table><h3 id="edition" tabindex="-1">Édition <a class="header-anchor" href="#edition" aria-label="Permalink to &quot;Édition&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Alt+L</code></td><td>Reformater le code automatiquement</td></tr><tr><td><code>Alt+Entrée</code></td><td>Afficher les suggestions de correction rapide</td></tr><tr><td><code>Ctrl+Space</code></td><td>Activer la complétion de code</td></tr></tbody></table><h3 id="refactorisation" tabindex="-1">Refactorisation <a class="header-anchor" href="#refactorisation" aria-label="Permalink to &quot;Refactorisation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Shift+F6</code></td><td>Renommer un élément partout dans le projet</td></tr><tr><td><code>Ctrl+Alt+C</code></td><td>Extraire une constante</td></tr><tr><td><code>Ctrl+Alt+M</code></td><td>Extraire une méthode</td></tr></tbody></table><h3 id="execution" tabindex="-1">Exécution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Exécution&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Shift+F10</code></td><td>Exécuter le programme</td></tr><tr><td><code>Shift+F9</code></td><td>Démarrer en mode débogage</td></tr><tr><td><code>F8</code></td><td>Avancer d&#39;une ligne en débogage</td></tr></tbody></table><h2 id="lecture-des-messages-d-erreur" tabindex="-1">Lecture des messages d&#39;erreur <a class="header-anchor" href="#lecture-des-messages-d-erreur" aria-label="Permalink to &quot;Lecture des messages d&#39;erreur&quot;">​</a></h2><p><em>Intellij</em> souligne les problèmes directement dans le code :</p><ul><li><strong>Rouge</strong> : erreur de compilation - le code ne peut pas s&#39;exécuter</li><li><strong>Jaune</strong> : avertissement - le code fonctionne mais pourrait être amélioré</li><li><strong>Gris</strong> : code inutilisé ou superflu</li></ul><div class="tip custom-block"><p class="custom-block-title">Utilise <code>Alt+Entrée</code></p><p>Quand <em>Intellij</em> souligne quelque chose, place le curseur dessus et appuie sur <code>Alt+Entrée</code> pour voir les suggestions de correction. C&#39;est souvent plus rapide que de chercher la solution manuellement.</p></div><h2 id="configuration-recommandee" tabindex="-1">Configuration recommandée <a class="header-anchor" href="#configuration-recommandee" aria-label="Permalink to &quot;Configuration recommandée&quot;">​</a></h2><h3 id="desactiver-la-completion-automatique-en-ligne" tabindex="-1">Désactiver la complétion automatique en ligne <a class="header-anchor" href="#desactiver-la-completion-automatique-en-ligne" aria-label="Permalink to &quot;Désactiver la complétion automatique en ligne&quot;">​</a></h3><p>Pour favoriser l&#39;apprentissage et éviter que l&#39;IDE complète le code à ta place :</p><p><strong>File → Settings → Editor → General → Inline Completion → décocher « Enable local Full Line completion suggestions »</strong></p><div class="warning custom-block"><p class="custom-block-title">À éviter en apprentissage</p><p>Ne laisse pas <em>Intellij</em> écrire le code à ta place. Utilise la complétion pour vérifier les noms exacts, mais tape le code toi-même pour mieux retenir la syntaxe.</p></div><div class="tip custom-block"><p class="custom-block-title">Configuration</p><p>Pour procéder à l’importation des réglages pour le cours de <strong>Programmation Objet I</strong>, lance <em>Intellij</em> puis va dans le menu <code>File &gt; Manage IDE settings &gt; Import Settings...</code>, importe le fichier de configuration disponible sur Léa</p></div><blockquote><p>Les réglages proposés incluent les règles de <strong>formatage pour le code</strong>, l’<strong>activation d’éléments d’assistance pour l’apprentissage</strong> de l’éditeur de code et la <strong>désactivation d’autres éléments pouvant nuire à l’apprentissage</strong> (notamment, mais pas exclusivement, les outils d’intelligence artificiels pour la génération de code)</p></blockquote><h3 id="police-et-lisibilite" tabindex="-1">Police et lisibilité <a class="header-anchor" href="#police-et-lisibilite" aria-label="Permalink to &quot;Police et lisibilité&quot;">​</a></h3><p><strong>File → Settings → Editor → Font</strong></p><div class="tip custom-block"><p class="custom-block-title">Votre prof!</p><p>Voici les réglages que j&#39;utilise pour mon environnement de développement pour maximiser la lisibilité du code et éviter des problèmes de posture futurs.</p></div><table tabindex="0"><thead><tr><th>Paramètre</th><th>Valeur recommandée</th></tr></thead><tbody><tr><td>Police</td><td>CaskaydiaCove Nerd Font (ou toute autre police à votre goût)</td></tr><tr><td>Taille</td><td>15</td></tr><tr><td>Interlignage</td><td>1.2</td></tr></tbody></table><p>Les polices <em>Nerd Fonts</em> sont disponibles sur <a href="https://www.nerdfonts.com/font-downloads" target="_blank" rel="noreferrer">nerdfonts.com</a>. Les polices <em>Nerd Fonts</em> offrent, ne plus d&#39;un typographie <code>monospace</code> un ensemble d&#39;icônes intégrés à la police</p><h3 id="theme-de-couleurs" tabindex="-1">Thème de couleurs <a class="header-anchor" href="#theme-de-couleurs" aria-label="Permalink to &quot;Thème de couleurs&quot;">​</a></h3><p><strong>File → Settings → Editor → Color Scheme</strong></p><p>Thème recommandé : <strong>Darcula Contrast</strong></p><h3 id="couleurs-de-couverture-de-tests" tabindex="-1">Couleurs de couverture de tests <a class="header-anchor" href="#couleurs-de-couverture-de-tests" aria-label="Permalink to &quot;Couleurs de couverture de tests&quot;">​</a></h3><p>Pour distinguer facilement les lignes couvertes des lignes non couvertes :</p><p><strong>File → Settings → Editor → Color Scheme → General → Line Coverage</strong></p>',39)),e("table",g,[t[7]||(t[7]=e("thead",null,[e("tr",null,[e("th",null,"Ligne"),e("th",null,"Propriété"),e("th",null,"Couleur")])],-1)),e("tbody",null,[e("tr",null,[t[1]||(t[1]=e("td",null,"Full (couverte)",-1)),t[2]||(t[2]=e("td",null,"Foreground",-1)),e("td",null,[o(r,{color:"#009200"})])]),e("tr",null,[t[3]||(t[3]=e("td",null,"Partial (partiellement couverte)",-1)),t[4]||(t[4]=e("td",null,"Foreground",-1)),e("td",null,[o(r,{color:"#ABAB00"})])]),e("tr",null,[t[5]||(t[5]=e("td",null,"Uncovered (non couverte)",-1)),t[6]||(t[6]=e("td",null,"Foreground",-1)),e("td",null,[o(r,{color:"#8F0000"})])])])])])}const C=a(m,[["render",h]]);export{k as __pageData,C as default};
